const c = $input.first().json;
const timestamp = Math.floor(Date.now() / 1000).toString();
const campaignId = (c.campaignId === undefined || c.campaignId === '') ? null : c.campaignId;
const content = {
  title: c.title,
  body: c.body,
  type: c.type,
  channel: c.channel
};
const bodyObj = {
  schemaVersion: '1',
  eventId: c.eventId,
  externalDraftId: c.externalDraftId,
  workflowId: $workflow.id,
  executionId: $execution.id,
  resumeUrl: $execution.resumeUrl,
  content: content,
  metadata: { agent: 'creator', promptVersion: 'mkt-03-v1' }
};
if (campaignId) bodyObj.campaignId = campaignId;
const projectId = $('Config Base URL').item.json.projectId || 'proj_aeon';
if (projectId) bodyObj.projectId = projectId;
// Serialize ONCE. rawBody is the exact bytes signed and transmitted.
const rawBody = JSON.stringify(bodyObj);
return [{ json: {
  eventId: c.eventId,
  externalDraftId: c.externalDraftId,
  timestamp: timestamp,
  rawBody: rawBody,
  hmacMessage: timestamp + '.' + rawBody,
  content: content,
  campaignId: campaignId
} }];

const j = $input.first().json;
const p = (j && j.body) ? j.body : j;
return [{ json: {
  schemaVersion: p.schemaVersion,
  decision: p.decision,
  contentId: p.contentId,
  revisionId: p.revisionId,
  contentHash: p.contentHash,
  title: p.title,
  body: p.body,
  channel: p.channel,
  campaignId: (p.campaignId === undefined || p.campaignId === "") ? null : p.campaignId,
  assets: p.assets ? p.assets : [],
  guardian: p.guardian ? p.guardian : null,
  review: p.review ? p.review : null
} }];

const j = $input.first().json;
const required = ['contentId','revisionId','contentHash','title','body','channel'];
const missing = [];
for (const k of required) {
  if (j[k] === undefined || j[k] === null || j[k] === '') missing.push(k);
}
if (missing.length) {
  throw new Error('APPROVED payload missing required fields: ' + missing.join(', ') + '. Failing closed; nothing published.');
}
// Pass through the EXACT human-approved revision. No AI/rewrite allowed here.
return [{ json: j }];

const a = $('Validate Approved Revision').item.json;
const chan = a.channel;
const fakeId = 'TEST-' + chan + '-' + $execution.id + '-' + Math.floor(Math.random() * 1000000);
return [{ json: {
  __staging: true,
  channel: chan,
  platformPostId: fakeId,
  platformUrl: 'https://staging.mock.local/' + String(chan).toLowerCase() + '/' + fakeId,
  publishedAt: new Date().toISOString(),
  note: 'STAGING MOCK — simulated publish, NOT a real post'
} }];

const a = $('Validate Approved Revision').item.json;
const pub = $input.first().json;
return [{ json: {
  __receiptStatus: 'PUBLISHED',
  contentId: a.contentId,
  revisionId: a.revisionId,
  contentHash: a.contentHash,
  channel: a.channel,
  platformPostId: pub.platformPostId,
  platformUrl: pub.platformUrl,
  publishedAt: pub.publishedAt
} }];

const a = $('Validate Approved Revision').item.json;
const e = $input.first().json;
const rawMsg = (e && e.error && (e.error.message || e.error)) ? (e.error.message || e.error) : 'Publish failed';
const msg = String(rawMsg).slice(0, 300);
return [{ json: {
  __receiptStatus: 'FAILED',
  contentId: a.contentId,
  revisionId: a.revisionId,
  contentHash: a.contentHash,
  channel: a.channel,
  errorCode: 'PUBLISH_FAILED',
  errorMessage: msg
} }];

const j = $input.first().json;
const timestamp = Math.floor(Date.now() / 1000).toString();
const base = {
  schemaVersion: '1',
  eventId: j.eventId,
  contentId: j.contentId,
  revisionId: j.revisionId,
  contentHash: j.contentHash,
  executionId: $execution.id,
  channel: j.channel
};
let bodyObj;
if (j.__receiptStatus === 'PUBLISHED') {
  // Control Room contract: SUCCESS | FAILED (SUCCESS flips Content.status to PUBLISHED)
  bodyObj = Object.assign({}, base, { status: 'SUCCESS', platformPostId: j.platformPostId, platformUrl: j.platformUrl, publishedAt: j.publishedAt });
} else {
  bodyObj = Object.assign({}, base, { status: 'FAILED', errorCode: j.errorCode, errorMessage: j.errorMessage });
}
const rawBody = JSON.stringify(bodyObj);
return [{ json: {
  timestamp: timestamp,
  rawBody: rawBody,
  hmacMessage: timestamp + '.' + rawBody
} }];

const item = $input.first().json;
let text = '';
if (typeof item.output === 'string') text = item.output;
else if (typeof item.text === 'string') text = item.text;
else if (item.message && typeof item.message.content === 'string') text = item.message.content;
else if (Array.isArray(item.choices) && item.choices[0]?.message?.content) text = item.choices[0].message.content;
else text = JSON.stringify(item);

const fence = text.match(/```(?:json)?\s*([\s\S]*?)```/i);
if (fence) text = fence[1];
const start = text.indexOf('{');
const end = text.lastIndexOf('}');
if (start >= 0 && end > start) text = text.slice(start, end + 1);

let parsed;
try { parsed = JSON.parse(text); } catch (e) {
  throw new Error('Creator LLM did not return valid JSON: ' + String(e.message || e));
}

const allowedTypes = ['TWITTER_THREAD','BLOG_POST','EMAIL','PRESS_RELEASE','AD_CREATIVE','VIDEO_SCRIPT','LINKEDIN_POST','DISCORD_MESSAGE'];
const allowedChannels = ['TWITTER','LINKEDIN','DISCORD','EMAIL','BLOG'];
const title = String(parsed.title || '').trim().slice(0, 200);
const body = String(parsed.body || '').trim();
const type = allowedTypes.includes(parsed.type) ? parsed.type : 'TWITTER_THREAD';
const channel = allowedChannels.includes(parsed.channel) ? parsed.channel : 'TWITTER';
if (!title || !body) throw new Error('Creator JSON missing title or body');

return [{ json: {
  title,
  body,
  type,
  channel,
  campaignId: parsed.campaignId === undefined || parsed.campaignId === '' ? null : parsed.campaignId,
  modelAlias: 'gpt-4o',
  promptVersion: 'mkt-03-v1',
  creatorStartedAt: new Date().toISOString()
} }];

const c = $input.first().json;
const eventId = 'ar-running-' + $execution.id + '-' + Date.now();
const projectId = $('Config Base URL').item.json.projectId || 'proj_aeon';
const bodyObj = {
  schemaVersion: '1',
  eventId,
  workflowId: $workflow.id,
  executionId: $execution.id,
  status: 'RUNNING',
  agentName: 'creator',
  modelAlias: c.modelAlias || 'gpt-4o',
  promptVersion: c.promptVersion || 'mkt-03-v1',
  startedAt: c.creatorStartedAt || new Date().toISOString(),
  projectId,
  metadata: { stage: 'creator' }
};
const timestamp = Math.floor(Date.now() / 1000).toString();
const rawBody = JSON.stringify(bodyObj);
return [{ json: Object.assign({}, c, {
  __agentRun: {
    timestamp,
    rawBody,
    hmacMessage: timestamp + '.' + rawBody
  }
}) }];

// HTTP Request may replace json; restore creator fields from Parse node
const c = $('MKT-03 ▪ Parse Creator JSON').item.json;
return [{ json: {
  title: c.title,
  body: c.body,
  type: c.type,
  channel: c.channel,
  campaignId: c.campaignId,
  modelAlias: c.modelAlias,
  promptVersion: c.promptVersion,
  creatorStartedAt: c.creatorStartedAt
} }];

const eventId = 'ar-wait-' + $execution.id + '-' + Date.now();
const started = $('MKT-03 ▪ Parse Creator JSON').item.json.creatorStartedAt;
const latencyMs = started ? Math.max(0, Date.now() - new Date(started).getTime()) : undefined;
const projectId = $('Config Base URL').item.json.projectId || 'proj_aeon';
const bodyObj = {
  schemaVersion: '1',
  eventId,
  workflowId: $workflow.id,
  executionId: $execution.id,
  status: 'WAITING_APPROVAL',
  agentName: 'creator',
  projectId,
  modelAlias: $('MKT-03 ▪ Parse Creator JSON').item.json.modelAlias || 'gpt-4o',
  promptVersion: $('MKT-03 ▪ Parse Creator JSON').item.json.promptVersion || 'mkt-03-v1',
  latencyMs,
  startedAt: started,
  metadata: { stage: 'awaiting_human' }
};
const timestamp = Math.floor(Date.now() / 1000).toString();
const rawBody = JSON.stringify(bodyObj);
return [{ json: {
  draftHandoff: $input.first().json,
  __agentRun: { timestamp, rawBody, hmacMessage: timestamp + '.' + rawBody }
} }];

const a = $('Validate Approved Revision').item.json;
const receipt = $('MKT-05 ▪ Normalize + Canonical Receipt Body').item.json;
let runStatus = 'FAILED';
try {
  const parsed = JSON.parse(receipt.rawBody);
  runStatus = parsed.status === 'SUCCESS' ? 'SUCCESS' : 'FAILED';
} catch (e) {
  runStatus = 'FAILED';
}
const eventId = 'ar-pub-' + $execution.id + '-' + Date.now();
const projectId = $('Config Base URL').item.json.projectId || 'proj_aeon';
const bodyObj = {
  schemaVersion: '1',
  eventId,
  workflowId: $workflow.id,
  executionId: $execution.id,
  status: runStatus,
  agentName: 'publisher',
  projectId,
  modelAlias: 'staging-mock',
  promptVersion: 'mkt-05-v1',
  finishedAt: new Date().toISOString(),
  metadata: { stage: 'publish_receipt', channel: a.channel, contentId: a.contentId, receiptStatus: runStatus }
};
const timestamp = Math.floor(Date.now() / 1000).toString();
const rawBody = JSON.stringify(bodyObj);
return [{ json: Object.assign({}, $input.first().json, {
  __agentRun: { timestamp, rawBody, hmacMessage: timestamp + '.' + rawBody }
}) }];

const projectId = $('Config Base URL').item.json.projectId || 'proj_aeon';
const campaignId = null; // optional: set a campaign CUID to enforce pause/stop/limits
const bodyObj = { schemaVersion: '1', projectId, include: ['contextPack'], ...(campaignId ? { campaignId } : {}) };
const timestamp = Math.floor(Date.now() / 1000).toString();
const rawBody = JSON.stringify(bodyObj);
return [{ json: {
  __policy: { timestamp, rawBody, hmacMessage: timestamp + '.' + rawBody, campaignId, projectId }
} }];

const j = $input.first().json;
if (j.allowed !== true) {
  throw new Error('Policy check blocked generation: ' + (j.reason || 'missing allowed=true') + '. Failing closed before LLM spend.');
}
return [{ json: { policyAllowed: true, policy: j } }];

const j = $input.first().json;
const policy = j.policy && typeof j.policy === 'object' ? j.policy : {};
const pack = policy.contextPack && typeof policy.contextPack === 'object' ? policy.contextPack : null;
const identity = (pack && pack.promptCore && pack.promptCore.identity && typeof pack.promptCore.identity === 'object')
  ? pack.promptCore.identity
  : {};
const name = (typeof identity.name === 'string' && identity.name.trim()) ? identity.name.trim() : 'AEON';
const legal = (typeof identity.legalName === 'string' && identity.legalName.trim())
  ? identity.legalName.trim()
  : 'Adaptive Liquidity';
const oneLiner = (typeof identity.oneLiner === 'string') ? identity.oneLiner.trim() : '';
const projectId = $('Config Base URL').item.json.projectId || 'proj_aeon';

const question = 'Which treasury-ops / on-chain cash-management products should ' + name + ' position against this week?';
const queryParts = [legal, name, 'competitors', 'institutional DeFi treasury operations on-chain cash management'];
if (oneLiner) queryParts.push(oneLiner);
const query = queryParts.filter(Boolean).join(' ').slice(0, 400);

const exaBody = {
  query: query,
  numResults: 8,
  type: 'auto',
  contents: { text: { maxCharacters: 1200 } }
};

const system = pack
  ? JSON.stringify(pack)
  : 'Follow Adaptive Liquidity / AEON brand voice. No yield promises. Do not invent sources.';

return [{ json: {
  policyAllowed: j.policyAllowed === true,
  policy: policy,
  contextPack: pack,
  projectId: projectId,
  question: question,
  query: query,
  exaBody: exaBody,
  system: system
} }];

const built = $('MKT-02 ▪ Build research task').item.json;
const exa = $input.first().json;
const results = Array.isArray(exa.results)
  ? exa.results
  : (exa.body && Array.isArray(exa.body.results) ? exa.body.results : []);

const hits = [];
const allowed = [];
for (let i = 0; i < results.length; i++) {
  const r = results[i] || {};
  const url = typeof r.url === 'string' ? r.url.trim() : '';
  const id = typeof r.id === 'string' ? r.id.trim() : '';
  if (!url && !id) continue;
  const sourceId = id || ('exa-' + (i + 1));
  const title = typeof r.title === 'string' ? r.title : '';
  const text = typeof r.text === 'string' ? r.text.slice(0, 1200) : '';
  hits.push({
    sourceId: sourceId,
    title: title.slice(0, 200),
    url: url || null,
    publishedDate: r.publishedDate || null,
    snippet: text
  });
  allowed.push(sourceId);
  if (url && url !== sourceId) allowed.push(url);
  if (id && id !== sourceId) allowed.push(id);
}

const user = [
  'Research question: ' + built.question,
  '',
  'Search hits (the ONLY allowed citations). Do not invent URLs, publishers, or source labels that are not in this list. If hits are empty, set evidence to [] and openQuestions to explain the gap. Do not invent competitors.',
  '',
  JSON.stringify(hits),
  '',
  'Return ONLY valid JSON (no markdown) with keys:',
  'schemaVersion ("1"),',
  'question (string, restated),',
  'summary (2-4 sentences, no yield promises),',
  'angles (array of up to 3 short campaign angles),',
  'risks (array of compliance risks to avoid),',
  'sources (array of { id, url, title } drawn ONLY from the search hits; empty array if no hits),',
  'evidence (array of { finding, sourceIds, confidence: HIGH|MEDIUM|LOW }),',
  'openQuestions (array of strings).',
  'Every sources[].url or sources[].id MUST match a search hit. Never fabricate citations.'
].join('\n');

return [{ json: {
  system: built.system,
  user: user,
  question: built.question,
  hits: hits,
  allowedSourceLocators: allowed,
  searchHitCount: hits.length
} }];

function extractText(item) {
  let text = '';
  if (typeof item.output === 'string') {
    text = item.output;
  } else if (Array.isArray(item.output)) {
    const parts = [];
    for (const msg of item.output) {
      if (!msg || typeof msg !== 'object') continue;
      const content = msg.content;
      if (typeof content === 'string') {
        parts.push(content);
        continue;
      }
      if (!Array.isArray(content)) continue;
      for (const part of content) {
        if (!part || typeof part !== 'object') continue;
        if (typeof part.output_text === 'string') parts.push(part.output_text);
        else if (typeof part.text === 'string') parts.push(part.text);
      }
    }
    text = parts.join('');
  } else if (typeof item.text === 'string') {
    text = item.text;
  } else if (item.message && typeof item.message.content === 'string') {
    text = item.message.content;
  } else if (Array.isArray(item.choices) && item.choices[0] && item.choices[0].message && typeof item.choices[0].message.content === 'string') {
    text = item.choices[0].message.content;
  } else {
    text = JSON.stringify(item);
  }
  return text;
}

function asNonEmptyString(v) {
  return typeof v === 'string' && v.trim().length > 0 ? v.trim() : '';
}

function locatorSet(list) {
  const s = new Set();
  if (!Array.isArray(list)) return s;
  for (const loc of list) {
    if (typeof loc === 'string' && loc.trim()) s.add(loc.trim());
  }
  return s;
}

function sourceMatches(src, allowed) {
  if (allowed.size === 0) return false;
  if (typeof src === 'string') {
    for (const loc of allowed) {
      if (src.indexOf(loc) !== -1) return true;
    }
    return false;
  }
  if (!src || typeof src !== 'object') return false;
  const url = asNonEmptyString(src.url);
  const id = asNonEmptyString(src.id);
  if (url && allowed.has(url)) return true;
  if (id && allowed.has(id)) return true;
  return false;
}

function toSourceLabel(src) {
  if (typeof src === 'string') return src.trim();
  if (!src || typeof src !== 'object') return '';
  const title = asNonEmptyString(src.title);
  const url = asNonEmptyString(src.url) || asNonEmptyString(src.id);
  return [title, url].filter(Boolean).join(' — ');
}

const item = $input.first().json;
let text = extractText(item);
const fence = text.match(/```(?:json)?\s*([\s\S]*?)```/i);
if (fence) text = fence[1];
const start = text.indexOf('{');
const end = text.lastIndexOf('}');
if (start >= 0 && end > start) text = text.slice(start, end + 1);

let parsed;
try {
  parsed = JSON.parse(text);
} catch (e) {
  throw new Error('Researcher returned non-JSON');
}
if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
  throw new Error('Researcher returned invalid shape (expected question + summary)');
}

const question = asNonEmptyString(parsed.question);
const summary = asNonEmptyString(parsed.summary);
if (!question || !summary) {
  throw new Error('Researcher returned invalid shape (expected question + summary)');
}

const prepared = $('MKT-02 ▪ Prepare researcher messages').item.json;
if (!prepared || typeof prepared !== 'object') {
  throw new Error('Missing Prepare researcher messages');
}
const allowed = locatorSet(prepared.allowedSourceLocators);
const searchHitCount = Number(prepared.searchHitCount) || 0;

const rawSources = Array.isArray(parsed.sources) ? parsed.sources : [];
const keptSources = [];
for (const src of rawSources) {
  if (searchHitCount === 0) continue;
  if (!sourceMatches(src, allowed)) continue;
  const label = toSourceLabel(src);
  if (label) keptSources.push(label);
}

const rawEvidence = Array.isArray(parsed.evidence) ? parsed.evidence : [];
const evidence = [];
for (const ev of rawEvidence) {
  if (searchHitCount === 0) continue;
  if (!ev || typeof ev !== 'object') continue;
  const finding = asNonEmptyString(ev.finding);
  if (!finding) continue;
  const ids = Array.isArray(ev.sourceIds)
    ? ev.sourceIds.filter((id) => typeof id === 'string' && allowed.has(id))
    : [];
  evidence.push({
    finding: finding,
    sourceIds: ids,
    confidence: asNonEmptyString(ev.confidence) || 'LOW'
  });
}

const angles = Array.isArray(parsed.angles)
  ? parsed.angles.filter((a) => typeof a === 'string' && a.trim()).map((a) => a.trim()).slice(0, 3)
  : [];
const risks = Array.isArray(parsed.risks)
  ? parsed.risks.filter((a) => typeof a === 'string' && a.trim()).map((a) => a.trim())
  : [];
const openQuestions = Array.isArray(parsed.openQuestions)
  ? parsed.openQuestions.filter((a) => typeof a === 'string' && a.trim()).map((a) => a.trim())
  : [];

if (searchHitCount === 0) {
  if (openQuestions.length === 0) {
    throw new Error('Researcher returned no search hits and no openQuestions');
  }
}

if (searchHitCount > 0 && keptSources.length === 0 && openQuestions.length === 0) {
  throw new Error('Researcher cited no search hits; add openQuestions or cite Exa URLs');
}

const research = {
  schemaVersion: '1',
  question: question,
  summary: summary,
  angles: angles,
  risks: risks,
  sources: keptSources,
  evidence: searchHitCount === 0 ? [] : evidence,
  openQuestions: openQuestions
};

return [{ json: {
  research: research,
  researchBrief: JSON.stringify(research),
  modelAliasResearch: 'gpt-4o-mini',
  promptVersionResearch: 'mkt-02-v2',
  searchHitCount: searchHitCount
} }];
